let connected=null;
function reflectWallet(){const message=document.querySelector('[data-checker-message]');if(message)message.textContent=connected?'Connected: '+connected:'Connect a wallet or search an EVM address.';const check=document.querySelector('[data-check-whitelist]');if(check)check.disabled=!connected;}
window.addEventListener('fillout:wallet',e=>{connected=e.detail?.account||null;reflectWallet();});
async function checkAddress(raw,result){try{const {getAddress}=await import('./ethers.mjs');const address=getAddress(raw.trim());if(/^0x0{40}$/i.test(address))throw Error();result.replaceChildren();const label=document.createElement('span');label.className='checker-address';label.textContent=address;const note=document.createElement('span');result.append(label,note);note.textContent='Checking…';const response=await fetch('/api/quests/eligibility?address='+encodeURIComponent(address),{cache:'no-store'});if(!response.ok){note.textContent='Checker temporarily unavailable. Please try again.';return;}const value=await response.json();note.textContent=value.published!==true?'The whitelist has not been published yet.':value.eligible===true?'Eligible':'Not eligible';}catch{result.textContent='Enter a valid EVM address, including 0x and all 40 hexadecimal characters.';}}
export function mountWhitelistChecker(app){app.innerHTML='<div class="local-heading"><p class="eyebrow">FILLOUT / WHITELIST CHECKER</p><h1>CHECK YOUR ACCESS.<span>✳</span></h1><p>Check your wallet or search an EVM address.</p></div><section class="checker-panel"><span class="checker-eye" aria-hidden="true">◈</span><h2>Whitelist checker</h2><p data-checker-message aria-live="polite"></p><div class="checker-actions"><button type="button" data-checker-connect>Connect wallet</button><button type="button" data-check-whitelist>Check connected wallet</button></div><form class="checker-search-form"><label for="checker-search-address">Search by EVM address</label><div class="checker-search-row"><input id="checker-search-address" type="text" maxlength="42" required placeholder="0x…" autocomplete="off" spellcheck="false"><button type="submit">Search address</button></div></form><p class="checker-result" data-checker-result role="status" aria-live="polite"></p></section>';reflectWallet();app.querySelector('[data-checker-connect]').onclick=()=>document.querySelector('#wallet-connect').click();app.querySelector('[data-check-whitelist]').onclick=()=>{if(connected)void checkAddress(connected,app.querySelector('[data-checker-result]'));};app.querySelector('.checker-search-form').onsubmit=e=>{e.preventDefault();void checkAddress(app.querySelector('#checker-search-address').value,app.querySelector('[data-checker-result]'));};}
